// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    address owner;

    function setUp() public { c = new SimpleWallet(); owner = address(this); }

    function testFuzz_property(uint256 amount, bool targetReverts) public {
        amount = bound(amount, 0, 1 ether);

        vm.deal(address(this), 2 ether);
        (bool okDeposit,) = address(c).call{value: amount}("");
        require(okDeposit);

        uint256 before = address(c).balance;
        assertTrue(before >= amount);

        address target;
        if (targetReverts) {
            Reverter r = new Reverter();
            target = address(r);
        } else {
            Receiver rcv = new Receiver();
            target = address(rcv);
        }

        bool ok;
        try c.sendMoney(target, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        if (!targetReverts) {
            assertTrue(ok);
            assertTrue(address(c).balance == before - amount);
        } else {
            assertTrue(true);
        }
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

contract Receiver {
    fallback() external payable {}
    receive() external payable {}
}
